import{_ as e,c as t,o as n,ai as o}from"./chunks/framework.BrjRfu4a.js";const c=JSON.parse('{"title":"국채시장 개관 | 의의 및 제도변천 | 한국 국채","description":"한국 국고채는 2년, 3년, 5년, 10년, 20년, 30년, 50년 만기의 고정금리 이표채와 인플레이션 위험을 제거할 수 있는 10년 만기의 물가연동국고채로 구성되어 있다. 발행 방식은 주로 국고채전문딜러(Primary Dealer, PD) 간 경쟁입찰을 통해 이루어지며, 비경쟁입찰 권한 행사나 국고채 교환 등을 통해서도 일부 발행된다.","frontmatter":{"title":"국채시장 개관 | 의의 및 제도변천 | 한국 국채","description":"한국 국고채는 2년, 3년, 5년, 10년, 20년, 30년, 50년 만기의 고정금리 이표채와 인플레이션 위험을 제거할 수 있는 10년 만기의 물가연동국고채로 구성되어 있다. 발행 방식은 주로 국고채전문딜러(Primary Dealer, PD) 간 경쟁입찰을 통해 이루어지며, 비경쟁입찰 권한 행사나 국고채 교환 등을 통해서도 일부 발행된다.","head":[["meta",{"property":"og:title","content":"국채시장 개관 | 의의 및 제도변천 | 한국 국채"}],["meta",{"property":"og:description","content":"한국 국고채는 2년, 3년, 5년, 10년, 20년, 30년, 50년 만기의 고정금리 이표채와 인플레이션 위험을 제거할 수 있는 10년 만기의 물가연동국고채로 구성되어 있다. 발행 방식은 주로 국고채전문딜러(Primary Dealer, PD) 간 경쟁입찰을 통해 이루어지며, 비경쟁입찰 권한 행사나 국고채 교환 등을 통해서도 일부 발행된다."}],["meta",{"property":"og:image","content":"/images/RiskQuantHaun.png"}],["meta",{"property":"og:url","content":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/foundations-and-evolution/"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/foundations-and-evolution/"}],["link",{"rel":"alternate","hreflang":"en","href":"https://risk-quant-haun.github.io/korean-treasury-bonds/foundations-and-evolution/"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/foundations-and-evolution/"}],["link",{"rel":"canonical","href":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/foundations-and-evolution/"}]],"date":"2025-03-01T00:00:00.000Z"},"headers":[],"relativePath":"ko/korean-treasury-bonds/foundations-and-evolution/index.md","filePath":"ko/korean-treasury-bonds/foundations-and-evolution/index.md"}'),r={name:"ko/korean-treasury-bonds/foundations-and-evolution/index.md"};function i(l,a,s,u,d,h){return n(),t("div",null,a[0]||(a[0]=[o('<h1 id="🏦-국채시장-개관" tabindex="-1">🏦 국채시장 개관 <a class="header-anchor" href="#🏦-국채시장-개관" aria-label="Permalink to &quot;🏦 국채시장 개관&quot;">​</a></h1><p><strong>의의 및 제도변천 | 한국 국채 | 2025.03.01</strong></p><h2 id="_1️⃣-한국-국채시장의-역사와-발전" tabindex="-1">1️⃣ 한국 국채시장의 역사와 발전 <a class="header-anchor" href="#_1️⃣-한국-국채시장의-역사와-발전" aria-label="Permalink to &quot;1️⃣ 한국 국채시장의 역사와 발전&quot;">​</a></h2><p>한국의 국채시장은 1950년 최초 국채발행 이후 괄목할 만한 성장을 이루었습니다. 특히 2000년 이후에는 국채의 원활한 발행과 유통시장 발전을 위한 다양한 제도와 인프라가 구축되면서, 국채시장이 전체 채권시장을 선도하는 중추적 역할을 담당하게 되었습니다.</p><h2 id="_2️⃣-현재-발행되는-국채의-종류" tabindex="-1">2️⃣ 현재 발행되는 국채의 종류 <a class="header-anchor" href="#_2️⃣-현재-발행되는-국채의-종류" aria-label="Permalink to &quot;2️⃣ 현재 발행되는 국채의 종류&quot;">​</a></h2><p>2024년 12월 기준으로 한국에서는 다음과 같은 5종류의 국채가 발행되고 있습니다:</p><div class="tip custom-block"><p class="custom-block-title">한국 국채의 종류</p><ul><li>국고채권(국고채)</li><li>개인투자용 국채</li><li>재정증권</li><li>국민주택채권(제1종)</li><li>외국환평형기금채권</li></ul></div><p>이 중에서 <strong>국고채</strong>가 국가재정자금 조달의 핵심적인 수단이자 국내 채권시장에서 지표채권(Benchmark) 역할을 수행하고 있습니다.</p><h2 id="_3️⃣-국채의-시장-비중" tabindex="-1">3️⃣ 국채의 시장 비중 <a class="header-anchor" href="#_3️⃣-국채의-시장-비중" aria-label="Permalink to &quot;3️⃣ 국채의 시장 비중&quot;">​</a></h2><p>국채는 전체 채권시장에서 매우 중요한 위치를 차지하고 있습니다:</p><ul><li>전체 채권 발행잔액 중 국고채 비중: 40.7%</li><li>전체 채권 거래량 중 국고채 비중: 59.1%</li></ul><p>이러한 수치는 국고채가 한국 채권시장에서 발행규모와 유동성 측면에서 모두 주도적 역할을 하고 있음을 잘 보여줍니다.</p><h2 id="_4️⃣-국고채의-특징" tabindex="-1">4️⃣ 국고채의 특징 <a class="header-anchor" href="#_4️⃣-국고채의-특징" aria-label="Permalink to &quot;4️⃣ 국고채의 특징&quot;">​</a></h2><p>국고채는 2년, 3년, 5년, 10년, 20년, 30년, 50년 만기의 고정금리 이표채와 인플레이션 위험을 제거할 수 있는 10년 만기의 물가연동국고채로 구성되어 있습니다.</p><p>발행 방식은 주로 국고채전문딜러(Primary Dealer, PD) 간 경쟁입찰을 통해 이루어지며, 비경쟁입찰 권한 행사나 국고채 교환 등을 통해서도 일부 발행됩니다.</p><p>정부는 국고채 발행계획을 사전에 공지하고 시장참여자와의 소통을 통해 다양한 의견을 정책에 반영함으로써 효율적이고 안정적인 국고채 발행을 위해 노력하고 있습니다.</p><h2 id="_5️⃣-유통시장에서의-국고채-역할" tabindex="-1">5️⃣ 유통시장에서의 국고채 역할 <a class="header-anchor" href="#_5️⃣-유통시장에서의-국고채-역할" aria-label="Permalink to &quot;5️⃣ 유통시장에서의 국고채 역할&quot;">​</a></h2><p>유통시장에서 국고채는 전체 채권 거래의 약 59%를 차지하면서 시장금리를 투명하고 효과적으로 형성시키는 지표채권으로서의 역할을 수행하고 있습니다.</p><p>최근에는 국채선물, Repo(환매조건부매매), ETF(상장지수펀드) 등 국고채 연관시장도 활성화되면서 안정적인 국고채 수급과 국채시장 효율화에 긍정적인 영향을 미치고 있습니다.</p>',19)]))}const k=e(r,[["render",i]]);export{c as __pageData,k as default};
